/* ================= V94: إنذار رسائل الواتساب ================= */
const WA_URL='wa.php';
let waState={}, waBusy=false, waFails=0;
function waLoad(){ try{ return JSON.parse(localStorage.getItem('safi_wa')||'{}') }catch(e){ return {} } }
function waSave(d){ try{ localStorage.setItem('safi_wa',JSON.stringify(d)) }catch(e){} }
let waData=waLoad(); if(!Array.isArray(waData.msgs)) waData.msgs=[];
function waNum(n){ n=String(n||''); return n.startsWith('964')?'0'+n.slice(3):n }
function waTime(ts){ const d=new Date(ts); return d.toLocaleTimeString('ar-IQ',{hour:'numeric',minute:'2-digit'}) }
function waShow(list,test){
  let ov=document.getElementById('waOv');
  const old=ov?JSON.parse(ov.dataset.list||'[]'):[];
  const all=test?[]:old.concat(list).slice(-6);
  if(!ov){ ov=document.createElement('div'); ov.id='waOv'; ov.className='al-ov wa-ov'; document.body.appendChild(ov); }
  ov.dataset.list=JSON.stringify(all);
  ov.innerHTML=`<div class="al-box" role="alertdialog" aria-modal="true" aria-labelledby="waT">
    <div class="al-t wa-t" id="waT">${test?'تجربة إنذار الواتساب':(all.length>1?all.length+' رسائل واتساب جديدة':'رسالة واتساب جديدة')}</div>
    <div class="al-list">${test?'<div class="al-row">هيج يطلع لما توصل رسالة. اضغط طفي.</div>':all.map(m=>`<div class="al-row wa-row"><b>${esc(m.name||waNum(m.from))}</b> <span class="wa-n">${esc(waNum(m.from))}</span><div class="wa-txt">${esc(m.text||'')}</div></div>`).join('')}</div>
    <button class="al-off" id="waOff">طفي الإنذار</button></div>`;
  ov.querySelector('#waOff').addEventListener('click',()=>{
    ov.remove();
    if(!document.getElementById('alarmOv')) alStop();
  });
  if(!alOn) alStart();
}
function waStatusUi(){
  const el=document.getElementById('waStatus'), q=document.getElementById('waQr'), rl=document.getElementById('waRelink');
  if(!el) return;
  const s=waState||{}; let t, cls='';
  if(waFails>2) { t='ما يوصل للموقع. تأكد من الإنترنت.'; cls='bad'; }
  else if(s.age===undefined) t='يفحص…';
  else if(s.age<0||s.age>90){ t='برنامج الواتساب طافي أو مو منصب بعد.'; cls='bad'; }
  else if(s.status==='open'){ t='شغال ✓ مربوط بالرقم '+waNum(s.me); cls='good'; }
  else if(s.qr){ t='امسح الكود من تلفون المطعم: واتساب ← الأجهزة المرتبطة ← ربط جهاز'; }
  else if(s.status==='reconnecting'||s.status==='starting'||s.status==='relink') t='يتصل…';
  else t='ينتظر الربط…';
  el.textContent=t; el.className='hint wa-st '+cls;
  if(q){
    if(s.qr&&s.status!=='open'&&s.age>=0&&s.age<=90){ if(q.dataset.qr!==s.qr){ q.dataset.qr=s.qr; q.innerHTML='<img alt="كود الربط" src="'+qrDataURL(s.qr)+'">'; } q.hidden=false; }
    else { q.hidden=true; q.dataset.qr=''; q.innerHTML=''; }
  }
  if(rl) rl.hidden=!(s.status==='open');
}
function waListUi(){
  const el=document.getElementById('waList'); if(!el) return;
  const l=waData.msgs.slice(-30).reverse();
  el.innerHTML=l.length?l.map(m=>`<div class="wa-item"><div class="wa-h"><b>${esc(m.name||waNum(m.from))}</b><span>${esc(waNum(m.from))} · ${waTime(m.at)}</span></div><div class="wa-txt">${esc(m.text||'')}</div></div>`).join(''):'<div class="hint">ماكو رسائل بعد.</div>';
}
async function waPoll(){
  if(waBusy) return; waBusy=true;
  try{
    const first=!waData.since;
    const r=await fetch(WA_URL+'?a=poll&since='+(waData.since||0),{headers:{'X-Safi-Key':bkKey()},cache:'no-store'});
    const j=await r.json();
    if(!j.ok) throw new Error(j.err||'x');
    waFails=0; waState=j.state||{};
    const msgs=(j.msgs||[]).filter(m=>!waData.msgs.some(x=>x.id===m.id));
    if(first){ waData.since=j.now; }   /* أول مرة: ما نزعج بالرسائل القديمة */
    else if(msgs.length){
      waData.since=Math.max(waData.since,...msgs.map(m=>m.at));
      waData.msgs=waData.msgs.concat(msgs).slice(-100);
      waShow(msgs,false); waListUi();
    }
    waSave(waData);
  }catch(e){ waFails++; }
  waBusy=false; waStatusUi();
}
setInterval(waPoll,8000); setTimeout(waPoll,1500);
document.addEventListener('visibilitychange',()=>{ if(!document.hidden) waPoll() });
document.getElementById('waTestBtn').addEventListener('click',()=>{ alUnlock(); waShow([],true) });
document.getElementById('waRelink').addEventListener('click',async()=>{
  if(!confirm('تفصل الرقم الحالي وتربط رقم جديد؟')) return;
  try{ await fetch(WA_URL+'?a=cmd',{method:'POST',headers:{'X-Safi-Key':bkKey(),'Content-Type':'application/json'},body:JSON.stringify({cmd:'relink'})}); toast('خلال دقيقة يطلع كود جديد'); }catch(e){ toast('ما وصل للموقع') }
});
waListUi(); waStatusUi();

