.al-ov.wa-ov{background:rgba(10,120,60,.6);animation:wap 1.1s infinite}
@keyframes wap{50%{background:rgba(10,120,60,.88)}}
.wa-ov .al-box{border-color:#3DDC84}
.wa-ov .al-t{color:#3DDC84}
.wa-ov .al-off{background:#3DDC84}
@media(prefers-reduced-motion:reduce){.al-ov.wa-ov{animation:none}}
.wa-row{text-align:right;padding:10px 12px;border-radius:12px;background:#1C1E22}
.wa-n{display:inline!important;direction:ltr;margin-right:6px}
.wa-txt{font-size:17px;margin-top:4px;white-space:pre-wrap;word-break:break-word}
.wa-st.good{color:#3DDC84}
.wa-st.bad{color:#FF6B5E}
.wa-qr{margin-top:12px;display:flex;justify-content:center}
.wa-qr img{width:240px;height:240px;background:#fff;padding:12px;border-radius:12px;image-rendering:pixelated}
.wa-list{margin-top:8px;max-height:360px;overflow-y:auto;display:grid;gap:8px}
.wa-item{padding:10px 12px;border:1px solid var(--line);border-radius:12px}
.wa-h{display:flex;justify-content:space-between;gap:8px;font-size:15px}
.wa-h span{color:var(--mute,#9296A0);font-size:13px;direction:ltr}
